const items = $input.all();
const finalItems = [];
const runId = Date.now(); 

// 🟢 تحديد المشهد المستهدف (المشهد الأوسط في الفيديو) لكي لا تتكرر الجملة 3 مرات 🟢
const targetSceneIndex = Math.floor(items.length / 2);

for (let i = 0; i < items.length; i++) {
  let item = items[i].json;

  let category = item.category || items[0].json.category || "story_craft";

  if (item.voiceover_ar && category !== 'promo') {

    let safeText = item.voiceover_ar.replace(/"/g, ' ').replace(/'/g, ' ').replace(/\n/g, ' ');

    if (item.title) {
        let safeTitle = item.title.replace(/"/g, ' ').replace(/'/g, ' ').replace(/\n/g, ' ');
        safeText = safeText.replace(safeTitle, ''); 
    }
    safeText = safeText.replace(/العنوان:/g, '').trim(); 

    // 🟢 السحر هنا: الزرع العضوي الذكي (لمشهد واحد فقط، وبعد اكتمال المعنى) 🟢
    if ((category === 'story_craft' || category === 'story_religion') && i === targetSceneIndex) {
        let wordsArray = safeText.split(/\s+/);
        let middleIndex = Math.floor(wordsArray.length / 2); 

        // البحث عن أقرب فاصلة أو نقطة بعد المنتصف لكي لا نقطع الجملة
        let insertIndex = middleIndex;
        for (let w = middleIndex; w < wordsArray.length; w++) {
            // إذا كانت الكلمة تنتهي بفاصلة، نقطة، أو علامة استفهام
            if (wordsArray[w].match(/[.،؟!]/)) {
                insertIndex = w + 1; // نزرع الجملة بعد هذه الكلمة
                break;
            }
        }

        // إضافة نقاط وفواصل لإجبار المعلق الصوتي (edge-tts) على التوقف لثانية وأخذ نفس
        let ctaText = ". ولا تنسوا الإعجاب والاشتراك في القناة .";
        let ctaWords = ctaText.split(" ");

        item.cta_start = insertIndex;
        item.cta_end = insertIndex + ctaWords.length - 1;

        // زرع الجملة في المكان الصحيح
        wordsArray.splice(insertIndex, 0, ...ctaWords);

        safeText = wordsArray.join(" ");
        item.voiceover_ar = safeText; 
    }

    let baseName = `voice_${runId}_scene_${item.scene_number || (i + 1)}`;
    let mp3FileName = `${baseName}.mp3`;
    let vttFileName = `${baseName}.vtt`; 

    let mp3Path = `${publicDir}\\${mp3FileName}`;
    let vttPath = `${publicDir}\\${vttFileName}`;

    let voiceRate = "+15%"; 
    if (category === 'story_religion') {
        voiceRate = "+5%";  
    }

    let cmd = `edge-tts --voice ar-SA-HamedNeural --rate="${voiceRate}" --pitch="-5Hz" --text "${safeText}" --write-media "${mp3Path}" --write-subtitles "${vttPath}"`;

    try {
      await runCommand(cmd);
      item.audio_url = mp3FileName; 
      item.audio_status = "Success";

      let maxSeconds = 0;

      if (fs.existsSync(vttPath)) {
        try {
            let vttContent = fs.readFileSync(vttPath, 'utf8');
            let timeRegex = /(?:(\d+):)?(\d+):(\d+)[.,](\d+)/g;
            let match;

            while ((match = timeRegex.exec(vttContent)) !== null) {
                let h = match[1] ? parseInt(match[1], 10) : 0;
                let m = parseInt(match[2], 10);
                let s = parseInt(match[3], 10);
                let msFraction = parseFloat(`0.${match[4]}`);
                let total = (h * 3600) + (m * 60) + s + msFraction;
                if (total > maxSeconds) maxSeconds = total;
            }
        } catch(e) {
            console.log("Error parsing VTT:", e.message);
        }
        try { fs.unlinkSync(vttPath); } catch(e) {}
      }

      if (maxSeconds === 0) {
          let wordsCount = safeText.split(/\s+/).length;
          maxSeconds = (wordsCount * 0.55) + 1; 
      }

      let audioDurationFrames = Math.ceil(maxSeconds * 30); 
      let exactFrames = audioDurationFrames + 30; 

      item.audioDurationFrames = audioDurationFrames; 
      item.durationInFrames = exactFrames; 

    } catch (error) {
      item.audio_status = "Failed";
      item.audio_error = error.message;
      item.audioDurationFrames = 0;
      item.durationInFrames = 150;
    }
  } else if (category === 'promo') {
    item.audio_status = "Skipped (Promo)";
    item.audio_url = "";
    item.durationInFrames = 120; 
    item.audioDurationFrames = 0;
  }

  finalItems.push({ json: item });
}

return finalItems;

