    let vttFileName = `${baseName}.vtt`; 

    let mp3Path = `${publicDir}\\${mp3FileName}`;
    let vttPath = `${publicDir}\\${vttFileName}`;

    let voiceRate = "+15%"; 
    if (category === 'story_religion') {
        voiceRate = "+5%";  
    }

    let cmd = `edge-tts --voice ar-SA-HamedNeural --rate="${voiceRate}" --pitch="-5Hz" --text "${safeText}" --write-media "${mp3Path}" --write-subtitles "${vttPath}"`;

    try {
      await runCommand(cmd);
      item.audio_url = mp3FileName; 
      item.audio_status = "Success";

      let maxSeconds = 0;

      if (fs.existsSync(vttPath)) {
        try {
            let vttContent = fs.readFileSync(vttPath, 'utf8');
            let timeRegex = /(?:(\d+):)?(\d+):(\d+)[.,](\d+)/g;
            let match;

            while ((match = timeRegex.exec(vttContent)) !== null) {
                let h = match[1] ? parseInt(match[1], 10) : 0;
                let m = parseInt(match[2], 10);
                let s = parseInt(match[3], 10);
                let msFraction = parseFloat(`0.${match[4]}`);
                let total = (h * 3600) + (m * 60) + s + msFraction;
                if (total > maxSeconds) maxSeconds = total;
            }
        } catch(e) {
            console.log("Error parsing VTT:", e.message);
        }
        try { fs.unlinkSync(vttPath); } catch(e) {}
      }

      if (maxSeconds === 0) {
          let wordsCount = safeText.split(/\s+/).length;
          maxSeconds = (wordsCount * 0.55) + 1; 
      }

      let audioDurationFrames = Math.ceil(maxSeconds * 30); 
      let exactFrames = audioDurationFrames + 30; 

      item.audioDurationFrames = audioDurationFrames; 
      item.durationInFrames = exactFrames; 

    } catch (error) {
      item.audio_status = "Failed";
      item.audio_error = error.message;
      item.audioDurationFrames = 0;
      item.durationInFrames = 150;
    }
  } else if (category === 'promo') {
    item.audio_status = "Skipped (Promo)";
    item.audio_url = "";
    item.durationInFrames = 120; 
    item.audioDurationFrames = 0;
  }

  finalItems.push({ json: item });
}

return finalItems;

