if (!fs.existsSync(publicDir)) fs.mkdirSync(publicDir, { recursive: true });

function removeTashkeel(text) {
    if (!text) return "";
    return text.replace(/[\u064B-\u0652\u0640]/g, "");
}

const preSelectedVideos = [];

for (let i = 0; i < items.length; i++) {
    let item = items[i].json;

    let category = item.category || "story_craft";
    let folderName = "nature"; // الافتراضي
    let isStory = false; // متغير لمعرفة هل هو محتوى قصصي أم مؤسسي

    // 🟢 1. تصحيح مسار المجلدات كما طلبت تماماً 🟢
    if (category === "story_craft") {
        folderName = "satisfying";      // الواقعي للمجلد satisfying
        isStory = true;
    } else if (category === "story_religion") {
        folderName = "nature";  // الديني للمجلد nature
        isStory = true;
    } else if (category === "promo") {
        folderName = "furniture";   // الإعلاني
    } else if (category === "advice") {
        folderName = "promo_wood";  // النصائح
    }

    let sourceFolder = `${baseBackgroundsDir}\\${folderName}`;

    let availableVideos = [];
    if (fs.existsSync(sourceFolder)) {
        availableVideos = fs.readdirSync(sourceFolder).filter(file => file.endsWith('.mp4'));
    }

    if (availableVideos.length === 0) {
        throw new Error(`المجلد ${sourceFolder} فارغ تماماً! يرجى إضافة فيديوهات.`);
    }

    // خلط عشوائي للفيديوهات
    for (let m = availableVideos.length - 1; m > 0; m--) {
        const j = Math.floor(Math.random() * (m + 1));
        [availableVideos[m], availableVideos[j]] = [availableVideos[j], availableVideos[m]];
    }

    preSelectedVideos.push({ sourceFolder, availableVideos, isStory });
}

const finalItems = [];
let videoIndex = 0;

for (let i = 0; i < items.length; i++) {
    let item = items[i].json;

    let currentFolderData = preSelectedVideos[i];
    let sourceFolder = currentFolderData.sourceFolder;
    let availableVideos = currentFolderData.availableVideos;
    let isStory = currentFolderData.isStory;

    if (videoIndex >= availableVideos.length) {
        videoIndex = 0; 
    }

    let selectedVideoUrls = [];

    // 🟢 2. السحر الديناميكي: حساب عدد الفيديوهات المطلوبة بناءً على مدة الصوت 🟢
    let videosPerScene = 1; // الافتراضي للمؤسسي (فيديو واحد فقط)

    if (isStory) {
        // محاولة استخراج مدة الصوت بالثواني من البيانات (مع وضع 60 ثانية كاحتياط أولي)
        let durationInSeconds = 60; 
        if (item.audioDurationFrames) {
            durationInSeconds = item.audioDurationFrames / 30; // تحويل الإطارات إلى ثواني
        } else if (item.audio_duration) {
            durationInSeconds = item.audio_duration;
        } else if (item.durationInFrames) {
            durationInSeconds = item.durationInFrames / 30;
        }

        // كل مقطع سيكون 6 ثواني، نقسم المدة الكلية على 6 ونقرب للأكبر
        const clipDurationSeconds = 6;
        videosPerScene = Math.ceil(durationInSeconds / clipDurationSeconds);

        // حماية: التأكد من سحب مقطع واحد على الأقل حتى لو كانت المدة قصيرة جداً
        if (videosPerScene < 1) videosPerScene = 1;
    }

    try {
        for (let v = 0; v < videosPerScene; v++) {
            // العودة لأول فيديو في المجلد إذا طلب الكود فيديوهات أكثر من المتاحة
            if (videoIndex >= availableVideos.length) videoIndex = 0; 

            let selectedVideoName = availableVideos[videoIndex];
            let sourceVideoPath = `${sourceFolder}\\${selectedVideoName}`;
            let localVideoName = `scene_${item.scene_number || (i + 1)}_part_${v}.mp4`;
            let targetVideoPath = `${publicDir}\\${localVideoName}`;

            if (fs.existsSync(targetVideoPath)) fs.unlinkSync(targetVideoPath);
            fs.copyFileSync(sourceVideoPath, targetVideoPath);

            selectedVideoUrls.push(localVideoName);
            videoIndex++;
        }

        if (item.voiceover_ar) {
            item.voiceover_ar = removeTashkeel(item.voiceover_ar);
        }

        // 🟢 3. توجيه المخرجات لبرنامج المونتاج 🟢
        if (isStory) {
            item.video_urls = selectedVideoUrls; // نرسل المصفوفة الديناميكية للقصص
            item.video_url = selectedVideoUrls[0]; 
            item.download_status = `Success (${videosPerScene} Alternating Clips)`;
        } else {
            item.video_urls = []; // نفرغ المصفوفة في الإعلاني لمنع التناوب
            item.video_url = selectedVideoUrls[0]; // نرسل فيديو واحد فقط
            item.download_status = "Success (Single Promo Video)";
        }

    } catch (e) {
        item.download_status = "Failed";
        item.video_urls = [];
        item.video_url = "";
        item.error_details = e.message;
    }

    finalItems.push({ json: item });
}

return finalItems;

